package com.isc.identityreference.persistence.oracle.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="identity_audit_event",indexes={@Index(name="ix_identity_audit_lookup",columnList="lookup_key_hash,occurred_at"),@Index(name="ix_identity_audit_retention",columnList="occurred_at")})
public class IdentityAuditEventEntity { @Id @Column(name="event_id",length=36) private String eventId; @Column(name="lookup_key_hash",length=128,nullable=false) private String lookupKeyHash; @Column(name="event_type",length=64,nullable=false) private String eventType; @Column(name="actor_type",length=32,nullable=false) private String actorType; @Column(name="reason_code",length=64) private String reasonCode; @Column(name="provider_id",length=128) private String providerId; @Column(name="policy_version") private Long policyVersion; @Column(name="from_state",length=32) private String fromState; @Column(name="to_state",length=32) private String toState; @Column(name="operation_id",length=36) private String operationId; @Column(name="occurred_at",nullable=false) private Instant occurredAt; public String getEventId(){return eventId;} public void setEventId(String v){eventId=v;} public String getLookupKeyHash(){return lookupKeyHash;} public void setLookupKeyHash(String v){lookupKeyHash=v;} public String getEventType(){return eventType;} public void setEventType(String v){eventType=v;} public String getActorType(){return actorType;} public void setActorType(String v){actorType=v;} public String getReasonCode(){return reasonCode;} public void setReasonCode(String v){reasonCode=v;} public String getProviderId(){return providerId;} public void setProviderId(String v){providerId=v;} public Long getPolicyVersion(){return policyVersion;} public void setPolicyVersion(Long v){policyVersion=v;} public String getFromState(){return fromState;} public void setFromState(String v){fromState=v;} public String getToState(){return toState;} public void setToState(String v){toState=v;} public String getOperationId(){return operationId;} public void setOperationId(String v){operationId=v;} public Instant getOccurredAt(){return occurredAt;} public void setOccurredAt(Instant v){occurredAt=v;} }
